from __future__ import annotations

import shutil
import urllib.request
import zipfile
from pathlib import Path, PurePosixPath, PureWindowsPath
from typing import Any

DOWNLOAD_TIMEOUT_SECONDS = 30


def open_url(
    url_or_request: str | urllib.request.Request,
    *,
    timeout: float = DOWNLOAD_TIMEOUT_SECONDS,
) -> Any:
    """Open a URL with an explicit timeout contract."""
    return urllib.request.urlopen(url_or_request, timeout=timeout)  # nosec B310


def download_url_to_path(
    url_or_request: str | urllib.request.Request,
    destination: Path,
    *,
    timeout: float = DOWNLOAD_TIMEOUT_SECONDS,
) -> None:
    """Stream a remote response to disk with a bounded network timeout."""
    destination.parent.mkdir(parents=True, exist_ok=True)
    with (
        open_url(url_or_request, timeout=timeout) as response,
        destination.open("wb") as output,
    ):
        shutil.copyfileobj(response, output)


def safe_extract_zip(zf: zipfile.ZipFile, destination: Path) -> None:
    """Extract a zip archive only if every member stays inside destination."""
    if destination is None:
        raise ValueError("destination must be provided")

    root = destination.resolve()
    members = zf.infolist()
    for member in members:
        member_name = member.filename
        normalized_name = member_name.replace("\\", "/")
        posix_path = PurePosixPath(normalized_name)
        windows_path = PureWindowsPath(member_name)

        if (
            not member_name
            or posix_path.is_absolute()
            or windows_path.is_absolute()
            or windows_path.drive
            or ".." in posix_path.parts
            or ".." in windows_path.parts
        ):
            raise ValueError(f"Unsafe path in archive: {member_name!r}")

        target = (root / Path(*posix_path.parts)).resolve()
        try:
            target.relative_to(root)
        except ValueError as exc:
            raise ValueError(f"Unsafe path in archive: {member_name!r}") from exc

    zf.extractall(root)
